    private var __score: Score!

    public var score: Score {
        get {
            return self.__score
        }
        set {
            self.__score = newValue
        }
    }

    public var currentTrack: Track? = nil

    public var currentStaff: Staff? = nil

    public var barIndex: Double = 0.0

    public var voiceIndex: Double = 0.0

    public var ignoredInitialVoice: Bool = false

    public var ignoredInitialStaff: Bool = false

    public var ignoredInitialTrack: Bool = false

    public var currentDuration: Duration = Duration.Quarter

    public var articulationUniqueIdToIndex: Map<String, Double> = Map<String, Double>()

    public var hasAnyProperData: Bool = false

    public var percussionArticulationNames: Map<String, String> = Map<String, String>()

    public var slurs: Map<String, Note> = Map<String, Note>()

    public var lyrics: Map<Double, List<Lyrics>> = Map<Double, List<Lyrics>>()

    public var sustainPedalToBeat: Map<SustainPedalMarker, Beat> = Map<SustainPedalMarker, Beat>()

    public var staffTuningApplied: Set<Staff> = Set<Staff>()

    public var staffNoteKind: Map<Staff, AlphaTexStaffNoteKind> = Map<Staff, AlphaTexStaffNoteKind>()

    public var staffHasExplicitTuning: Set<Staff> = Set<Staff>()

    public var staffHasExplicitDisplayTransposition: Set<Staff> = Set<Staff>()

    public var staffDisplayTranspositionApplied: Set<Staff> = Set<Staff>()

    public var staffInitialClef: Map<Staff, Clef> = Map<Staff, Clef>()

    public var syncPoints: List<FlatSyncPoint> = List<FlatSyncPoint>()

    public var currentDynamics: DynamicValue = DynamicValue.F

    public var accidentalMode: AlphaTexAccidentalMode = AlphaTexAccidentalMode.Explicit

    public var voiceMode: AlphaTexVoiceMode = AlphaTexVoiceMode.StaffWise

    public var currentTupletNumerator: Double = -1.0

    public var currentTupletDenominator: Double = -1.0

    public var scoreNode: AlphaTexScoreNode? = nil

    public init() {}
}
